import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"kiwa v1.35 released — Observability 深化 II (@kiwa-lab/observability v2.1.0 + 8 axis advanced observability + 縦深化 pair 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.35/zenn-article.md","filePath":"announcements/v1.35/zenn-article.md"}'),o={name:"announcements/v1.35/zenn-article.md"};function l(n,e,s,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v1-35-released-—-observability-深化-ii-kiwa-lab-observability-v2-1-0-8-axis-advanced-observability-縦深化-pair-第-7-pair-連続化-3-stage-拡張-pattern-2-例目" tabindex="-1">kiwa v1.35 released — Observability 深化 II (@kiwa-lab/observability v2.1.0 + 8 axis advanced observability + 縦深化 pair 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目) <a class="header-anchor" href="#kiwa-v1-35-released-—-observability-深化-ii-kiwa-lab-observability-v2-1-0-8-axis-advanced-observability-縦深化-pair-第-7-pair-連続化-3-stage-拡張-pattern-2-例目" aria-label="Permalink to &quot;kiwa v1.35 released — Observability 深化 II (@kiwa-lab/observability v2.1.0 + 8 axis advanced observability + 縦深化 pair 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><strong>kiwa v1.35 released</strong> — Observability 深化 II milestone (advanced observability semantics 8 axis + real driver + 縦深化 pair 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目)</li><li><strong><code>@kiwa-lab/observability</code> v2.0.0 → v2.1.0 minor bump</strong> — 8 axis advanced observability semantics + real driver env-gate + 4 provider × 8 axis neutral state machine 追加</li><li><strong>8 axis semantics</strong> = slo-burn-rate + red-use-golden-signals + exemplar-tracing + otel-advanced + log-correlation-advanced + alert-routing-advanced + continuous-profiling + cardinality-control</li><li><strong>3 dogfood app v2 / 新規</strong> — observability-slo-app v2 + otel-exemplar-app v2 + profiling-app 新規、 全 7 軸 release gate PASS + real driver env-gate</li><li><strong>縦深化 pair pattern 第 7 pair 連続化</strong> — Auth pair (v1.21→v1.22) + Realtime pair (v1.13→v1.28) + Streaming pair (v1.20→v1.31) + Database pair (v1.14→v1.32) + Payment pair (v1.14→v1.23→v1.33) + Frontend pair (v1.16→v1.34) + <strong>Observability pair (v1.14→v1.17→v1.35)</strong>、 3-stage 拡張 pattern は Payment + Observability の 2 例、 縦深化戦略 SSOT を observability production layer に拡張</li><li><strong>13 milestone 連続 snippet validation streak</strong> (v1.23-v1.35)</li><li><strong>kiwa runtime fixture 35 packages 維持</strong> (observability 既存 package の minor 拡張)</li><li>v1.11 以降 25 milestone 連続完遂</li></ul><h2 id="v1-35-が解決したい問題-—-observability-production-semantics-の-testing-gap" tabindex="-1">v1.35 が解決したい問題 — Observability production semantics の testing gap <a class="header-anchor" href="#v1-35-が解決したい問題-—-observability-production-semantics-の-testing-gap" aria-label="Permalink to &quot;v1.35 が解決したい問題 — Observability production semantics の testing gap&quot;">​</a></h2><p>v1.14 で <code>@kiwa-lab/observability</code> v1.0 (OpenTelemetry / Datadog / Sentry の 3 provider を統一 mock として提供する telemetry collector envelope) を land、 v1.17 で v2.0 に major bump (Grafana-style DashboardMock + Prometheus AlertManager-style AlertRouter + trace flame graph + LogCorrelationIndex の 4 module 追加、 v1 telemetry mock 基盤上に v2 dashboard/alert/flame graph/log correlation の 6 base semantics layer を確立) した時点で、 kiwa は telemetry provider mock + observability dashboard/alerting のうち base semantics までは cover していた。 broker binary + Grafana Enterprise + Prometheus + Loki 不要で mock only mode で走る、 実 test 環境の inner-loop 速度を確保する目的の layer。</p><p>しかし v1.17 v2.0 land 後の実行観測で判明したのは、 real production observability setup (Grafana OSS + Prometheus + Loki + OpenTelemetry Collector + pyroscope + eBPF profiler) で頻繁に遭遇する <strong>8 axis の advanced observability semantics</strong> — SLO burn rate の multi-window multi-burn-rate alert (5m/1h/6h/3d) 設計 error / RED/USE/four golden signals の service dependency graph 統一 / exemplar tracing の trace-to-metric / metric-to-trace 双方向 navigation / OTel batch processor + resource detection + baggage 3 axis の統一 / structured log の trace_id/span_id auto-injection + LogQL/PromQL join / alert routing の silence + inhibit + escalation ladder 3 axis / continuous profiling の pyroscope/parca/eBPF 3 provider 統一 + on-CPU/off-CPU/memory profile 3 axis / cardinality control の high-cardinality detection + label reduction + DDSketch/t-digest 統一 — が v1.17 v2.0 の 6 base semantics だけでは cover できないこと。</p><p>v1.35 はこの gap を埋める深化 milestone。 8 axis advanced observability semantics + real driver env-gate + 3 dogfood observability app v2 / 新規 で <strong>production observability testing SSOT</strong> を確立、 kiwa の縦深化 pair pattern を 7 pair 目として observability production layer に拡張、 かつ Payment (v1.14 → v1.23 → v1.33) と同構造の <strong>3-stage 拡張 pattern の 2 例目</strong> として (v1.14 → v1.17 → v1.35)。</p><h2 id="v1-35-で追加した-8-axis-advanced-observability-semantics" tabindex="-1">v1.35 で追加した 8 axis advanced observability semantics <a class="header-anchor" href="#v1-35-で追加した-8-axis-advanced-observability-semantics" aria-label="Permalink to &quot;v1.35 で追加した 8 axis advanced observability semantics&quot;">​</a></h2><h3 id="_1-slo-burn-rate-slo-burn-rate-ts" tabindex="-1">1. SLO burn rate (<code>slo-burn-rate.ts</code>) <a class="header-anchor" href="#_1-slo-burn-rate-slo-burn-rate-ts" aria-label="Permalink to &quot;1. SLO burn rate (`slo-burn-rate.ts`)&quot;">​</a></h3><p>SLO/SLI definition + error budget calculation + multi-window multi-burn-rate alert (5m / 1h / 6h / 3d の 4 window × short-window &amp; long-window pair で fast burn / slow burn を分別) + budget consumption tracking (99.9% availability SLO で 30 day 期間中の budget 消費速度追跡) の 4 axis を pure state machine として実装。 <code>defineSlo</code> → <code>computeErrorBudget</code> → <code>evaluateBurnRateAlert</code> → <code>trackBudgetConsumption</code> の 4 event envelope。 real driver env-gate で Prometheus alertmanager 実 rules に routing。</p><h3 id="_2-red-use-four-golden-signals-red-use-golden-signals-ts" tabindex="-1">2. RED / USE / four golden signals (<code>red-use-golden-signals.ts</code>) <a class="header-anchor" href="#_2-red-use-four-golden-signals-red-use-golden-signals-ts" aria-label="Permalink to &quot;2. RED / USE / four golden signals (`red-use-golden-signals.ts`)&quot;">​</a></h3><p>RED (Rate / Errors / Duration) + USE (Utilization / Saturation / Errors) + four golden signals (latency / traffic / errors / saturation) + service dependency graph の 4 axis 統一実装。 <code>emitRedMetric</code> → <code>emitUseMetric</code> → <code>emitGoldenSignal</code> → <code>buildServiceDependencyGraph</code> の 4-event envelope。</p><h3 id="_3-exemplar-tracing-exemplar-tracing-ts" tabindex="-1">3. Exemplar tracing (<code>exemplar-tracing.ts</code>) <a class="header-anchor" href="#_3-exemplar-tracing-exemplar-tracing-ts" aria-label="Permalink to &quot;3. Exemplar tracing (`exemplar-tracing.ts`)&quot;">​</a></h3><p>trace-to-metric exemplar attachment (histogram bucket に対応する trace の attach) + metric-to-trace navigation (metric alert → 該当 trace への drill-down) + histogram bucket exemplar (per-bucket 代表 trace) + Prometheus native histogram exemplar (v2.40+ native histogram の exemplar 対応) の 4 axis 統一実装。</p><h3 id="_4-opentelemetry-advanced-otel-advanced-ts" tabindex="-1">4. OpenTelemetry advanced (<code>otel-advanced.ts</code>) <a class="header-anchor" href="#_4-opentelemetry-advanced-otel-advanced-ts" aria-label="Permalink to &quot;4. OpenTelemetry advanced (`otel-advanced.ts`)&quot;">​</a></h3><p>OpenTelemetry batch processor (SDK 側 batching + backpressure) + resource detection (host / process / k8s / cloud attribute の自動検出) + W3C context propagation (traceparent + tracestate header の parse / build) + baggage propagation (cross-service context 伝播 baggage: key=value) + semantic conventions v1.27 準拠 の 4 axis 統一実装。</p><h3 id="_5-log-correlation-advanced-log-correlation-advanced-ts" tabindex="-1">5. Log correlation advanced (<code>log-correlation-advanced.ts</code>) <a class="header-anchor" href="#_5-log-correlation-advanced-log-correlation-advanced-ts" aria-label="Permalink to &quot;5. Log correlation advanced (`log-correlation-advanced.ts`)&quot;">​</a></h3><p>structured log (JSON structured logging + severity + trace_id/span_id field) + trace_id/span_id auto-injection (log SDK integration) + LogQL (Loki query) + PromQL join (metric ↔ log ↔ trace の 3 correlation key join) + span event correlation (log line ↔ span event) の 4 axis 統一実装。</p><h3 id="_6-alert-routing-advanced-alert-routing-advanced-ts" tabindex="-1">6. Alert routing advanced (<code>alert-routing-advanced.ts</code>) <a class="header-anchor" href="#_6-alert-routing-advanced-alert-routing-advanced-ts" aria-label="Permalink to &quot;6. Alert routing advanced (`alert-routing-advanced.ts`)&quot;">​</a></h3><p>silence (時間窓 + label matcher で alert 抑止) + inhibit (higher severity alert 発火時に lower severity 抑止) + escalation ladder (未 ack alert の段階 escalation) + oncall rotation (PagerDuty schedule + primary / secondary rotation) + PagerDuty / Slack / OpsGenie routing の 4 axis 統一実装。</p><h3 id="_7-continuous-profiling-continuous-profiling-ts" tabindex="-1">7. Continuous profiling (<code>continuous-profiling.ts</code>) <a class="header-anchor" href="#_7-continuous-profiling-continuous-profiling-ts" aria-label="Permalink to &quot;7. Continuous profiling (`continuous-profiling.ts`)&quot;">​</a></h3><p>pyroscope / parca profile ingestion (pprof format + parca-style profile schema) + eBPF profiler (Linux kernel eBPF program で system-wide profile 収集) + on-CPU / off-CPU / memory profile (3 profile type 分別) + flame graph render (SVG + interactive drill-down) + depth-first flatten (flame graph の stack trace flatten + hot path 抽出) の 4 axis 統一実装。</p><h3 id="_8-cardinality-control-cardinality-control-ts" tabindex="-1">8. Cardinality control (<code>cardinality-control.ts</code>) <a class="header-anchor" href="#_8-cardinality-control-cardinality-control-ts" aria-label="Permalink to &quot;8. Cardinality control (`cardinality-control.ts`)&quot;">​</a></h3><p>high-cardinality detection (label 組合せ爆発の検出 + threshold 超過 alert) + label reduction (drop_label / relabel_config で cardinality 削減) + histogram / summary / sketch (DDSketch + t-digest の approximate quantile) + cardinality budget enforcement (per-metric cardinality budget + drop policy) の 4 axis 統一実装。</p><h2 id="_3-dogfood-observability-app-v2-新規" tabindex="-1">3 dogfood observability app v2 / 新規 <a class="header-anchor" href="#_3-dogfood-observability-app-v2-新規" aria-label="Permalink to &quot;3 dogfood observability app v2 / 新規&quot;">​</a></h2><h3 id="dogfood-observability-slo-app-v2-v1-35-2-issue-1063" tabindex="-1"><code>dogfood-observability-slo-app</code> v2 (v1.35-2, Issue #1063) <a class="header-anchor" href="#dogfood-observability-slo-app-v2-v1-35-2-issue-1063" aria-label="Permalink to &quot;`dogfood-observability-slo-app` v2 (v1.35-2, Issue #1063)&quot;">​</a></h3><ul><li>SLO burn rate + error budget + multi-window multi-burn-rate alert 5m/1h/6h/3d + Prometheus alertmanager mock + Grafana OSS testcontainers real driver</li><li>testcontainers-shaped env-gate、 mock only + <code>KIWA_MODE=real PROMETHEUS_URL=... GRAFANA_URL=...</code> opt-in の 2 layer 走査</li><li>SLO SSOT walkthrough (99.9% availability SLO の budget 消費 + burn rate alert design)</li></ul><h3 id="dogfood-otel-exemplar-app-v2-v1-35-3-issue-1064" tabindex="-1"><code>dogfood-otel-exemplar-app</code> v2 (v1.35-3, Issue #1064) <a class="header-anchor" href="#dogfood-otel-exemplar-app-v2-v1-35-3-issue-1064" aria-label="Permalink to &quot;`dogfood-otel-exemplar-app` v2 (v1.35-3, Issue #1064)&quot;">​</a></h3><ul><li>OpenTelemetry Collector + exemplar tracing + trace-to-metric + baggage propagation + W3C context propagation traceparent/tracestate</li><li>testcontainers-shaped env-gate、 OTel Collector real driver 経路 (<code>OTEL_COLLECTOR_URL=...</code>)</li><li>exemplar attachment + metric-to-trace navigation + baggage cross-service 伝播 の walkthrough</li></ul><h3 id="dogfood-profiling-app-新規-v1-35-4-issue-1065" tabindex="-1"><code>dogfood-profiling-app</code> (新規, v1.35-4, Issue #1065) <a class="header-anchor" href="#dogfood-profiling-app-新規-v1-35-4-issue-1065" aria-label="Permalink to &quot;`dogfood-profiling-app` (新規, v1.35-4, Issue #1065)&quot;">​</a></h3><ul><li>Continuous profiling + pyroscope + eBPF + on-CPU/off-CPU/memory profile + flame graph render</li><li>testcontainers-shaped env-gate、 pyroscope testcontainers real driver 経路</li><li>pyroscope / parca / eBPF の 3 provider 統一 + flame graph SVG render + depth-first flatten walkthrough</li></ul><h2 id="縦深化-pair-pattern-第-7-pair-連続化-3-stage-拡張-pattern-2-例目" tabindex="-1">縦深化 pair pattern 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目 <a class="header-anchor" href="#縦深化-pair-pattern-第-7-pair-連続化-3-stage-拡張-pattern-2-例目" aria-label="Permalink to &quot;縦深化 pair pattern 第 7 pair 連続化 + 3-stage 拡張 pattern 2 例目&quot;">​</a></h2><p>v1.35 で kiwa の縦深化 pair pattern (basic mock milestone → 深化 II milestone で real driver + advanced semantics) が <strong>7 pair 連続完成</strong>。 特に Payment (v1.14 → v1.23 → v1.33) と Observability (v1.14 → v1.17 → v1.35) は <strong>3-stage 拡張 pattern</strong> で、 base mock → mid depth → advanced real driver の 3 段拡張パターン (2 例):</p><ol><li><strong>Auth pair</strong> (v1.21 → v1.22) <ul><li>v1.21 = <code>@kiwa-lab/auth</code> v0.4 4 protocol adapter (WebAuthn L3 / Passkey / OAuth 2.1 / OIDC) mock only</li><li>v1.22 = Keycloak testcontainers + oauth2-mock-server + Chrome caBLE hybrid transport (real driver) + a11y axe-core gate</li></ul></li><li><strong>Realtime pair</strong> (v1.13 → v1.28) <ul><li>v1.13 = <code>@kiwa-lab/realtime</code> v0.1 4 provider (Supabase / Ably / Pusher / Socket.io) × 5 base semantics mock only</li><li>v1.28 = WebRTC + WebTransport + HTTP/3 + QUIC multiplexing + 8 axis advanced (real driver env-gate)</li></ul></li><li><strong>Streaming pair</strong> (v1.20 → v1.31) <ul><li>v1.20 = <code>@kiwa-lab/streaming</code> v0.1 3 provider (Kafka / Redpanda / NATS) × 5 semantics mock only</li><li>v1.31 = Kafka raw + Redpanda schema + NATS JetStream + 8 axis advanced (real driver env-gate + testcontainers)</li></ul></li><li><strong>Database pair</strong> (v1.14 → v1.32) <ul><li>v1.14-v1.26 = <code>@kiwa-lab/orm</code> v0.1-v0.9 3 ORM × 3 backend + 8 base semantics mock only</li><li>v1.32 = Postgres logical replication + MySQL cluster + SQLite WAL/FTS5 + 8 axis advanced (real driver env-gate + testcontainers)</li></ul></li><li><strong>Payment pair</strong> (v1.14 → v1.23 → v1.33) 【3-stage 拡張 pattern 1 例目】 <ul><li>v1.14 = <code>@kiwa-lab/payment</code> v0.1 3 provider webhook mock (Stripe / Paddle / Lemon Squeezy)</li><li>v1.23 = <code>@kiwa-lab/payment</code> v0.3 9 base billing semantics (subscription lifecycle + invoice + 3DS v2 + SCA + PSD2 + VAT/GST + dispute + refund + coupon)</li><li>v1.33 = <code>@kiwa-lab/payment</code> v0.4 8 advanced billing II semantics + real driver env-gate + Stripe Connect + Paddle Billing v2 + Lemon Squeezy license</li></ul></li><li><strong>Frontend pair</strong> (v1.16 → v1.34) <ul><li>v1.16 = <code>@kiwa-lab/component</code> v0.1-v0.2 3 target (Storybook 8 / Playwright CT / Chromatic) 6 base semantics mock only</li><li>v1.34 = <code>@kiwa-lab/component</code> v0.3 + <code>@kiwa-lab/nextjs</code> v1.2 8 axis advanced frontend semantics + real driver env-gate + Next.js 15 App Router + Storybook 8 MDX + Playwright CT + Chromatic</li></ul></li><li><strong>Observability pair</strong> (v1.14 → v1.17 → v1.35、 this) 【3-stage 拡張 pattern 2 例目】 <ul><li>v1.14 = <code>@kiwa-lab/observability</code> v1.0 3 provider mock (OpenTelemetry / Datadog / Sentry) + span + metric + log + exception + transaction 統一 collector</li><li>v1.17 = <code>@kiwa-lab/observability</code> v2.0 Grafana-style DashboardMock + Prometheus AlertManager-style AlertRouter + trace flame graph + LogCorrelationIndex の 4 module 追加 (v1 telemetry mock 基盤上に v2 dashboard / alert / flame graph / log correlation の 6 base semantics layer)</li><li>v1.35 = <code>@kiwa-lab/observability</code> v2.1 8 advanced observability semantics + real driver env-gate + Grafana OSS + Prometheus + Loki + OTel Collector</li></ul></li></ol><p>basic mock → (mid depth →) advanced real driver の 2 phase (+ 3-stage 拡張 2 例) pair を追加領域に横展開する pattern が SSOT 化された。 v1.25 perf + v1.27 mutation + v1.30 a11y の横串 triple pair と合わせて <strong>kiwa quality gate 縦横 grid maximum extension</strong>、 7 領域 (auth / realtime / streaming / database / payment / frontend / observability) 完全 cover。</p><h2 id="v1-11-以降-25-milestone-連続完遂" tabindex="-1">v1.11 以降 25 milestone 連続完遂 <a class="header-anchor" href="#v1-11-以降-25-milestone-連続完遂" aria-label="Permalink to &quot;v1.11 以降 25 milestone 連続完遂&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (非決定性) → v1.13 (時間軸) → v1.14 (横軸拡張) → v1.15 (AI-LLM 深化) → v1.16 (component 縦軸) → v1.17 (Observability v2) → v1.18 (Blockchain 深化) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → v1.23 (Payment 深化) → v1.24 (Edge / Serverless 深化) → v1.25 (Perf-harness sweep) → v1.26 (Database 深化) → v1.27 (Mutation testing sweep) → v1.28 (Realtime 深化 II) → v1.29 (release script filter SSOT) → v1.30 (a11y 横串 sweep) → v1.31 (Streaming 深化 II) → v1.32 (Database 深化 II) → v1.33 (Payment 深化 II) → v1.34 (Frontend 深化) → <strong>v1.35 (Observability 深化 II)</strong>。</p><h2 id="_13-milestone-連続-snippet-validation-streak" tabindex="-1">13 milestone 連続 snippet validation streak <a class="header-anchor" href="#_13-milestone-連続-snippet-validation-streak" aria-label="Permalink to &quot;13 milestone 連続 snippet validation streak&quot;">​</a></h2><p>v1.23 (payment 深化) から v1.35 (observability 深化 II) まで <strong>13 milestone 連続で snippet validation pattern</strong> を land 済:</p><p>payment-v1.23 / edge-v1.24 / perf-harness-v1.25 / orm-v1.26 / quality-metrics-v1.27 / realtime-v1.28 / release-invariants-v1.29 / a11y-v1.30 / streaming-v1.31 / orm-v1.32 / payment-v1.33 / frontend-v1.34 / <strong>observability-v1.35</strong>。</p><p>各 milestone の tutorial code snippet はすべて <code>docs-tutorial-v1.XX.test.ts</code> で自動検証されている (<code>packages/observability/tests/docs-tutorial-v1.35.test.ts</code> は 13 milestone 目の追加)。</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/observability</span></span></code></pre></div><p>Migration guide (additive-only、 breaking change なし):</p><ul><li><a href="https://cardene777.github.io/kiwa/migrations/v1.34-to-v1.35" target="_blank" rel="noreferrer">v1.34 → v1.35 migration guide</a></li><li><a href="https://cardene777.github.io/kiwa/concepts/observability-real-driver-testing" target="_blank" rel="noreferrer">Observability real-driver testing SSOT concept doc</a></li></ul><h2 id="v2-0-で解決したい問題" tabindex="-1">v2.0 で解決したい問題 <a class="header-anchor" href="#v2-0-で解決したい問題" aria-label="Permalink to &quot;v2.0 で解決したい問題&quot;">​</a></h2><ul><li>Multi-version Vitest matrix — Vitest 1.x vs 2.x vs 3.x parity check</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapter</li><li>Coverage 100 % milestone</li><li>Cache depth II — Dragonfly + KeyDB failover + Redis cluster resharding + eviction ML</li><li>Queue depth II — BullMQ Pro + Inngest Fn v2 + AWS SQS FIFO + RabbitMQ federation</li><li>AI-LLM depth II — Anthropic Messages Batch API + OpenAI Realtime API + Vercel AI SDK v4 + LangGraph fan-out</li><li>Search depth II — Meilisearch cluster + Algolia rules + Typesense sharding + vector hybrid re-ranking</li><li>L2 depth — Base / Arbitrum / Optimism / Scroll block-space fidelity</li><li>ZK depth — Noir / Circom / RISC Zero test harness</li><li>IoT depth — MQTT / CoAP / LWM2M</li><li>DB depth III — SurrealDB / EdgeDB / Turso / CockroachDB / TimescaleDB / QuestDB</li><li>Streaming depth III — Pulsar + KsqlDB + Faust + Flink + Beam pipeline fidelity</li><li>Auth depth III — WebAuthn L3 + Passkey caBLE + Federation + Verifiable Credentials</li><li>Perf-harness sweep II — real-machine baseline、 macOS ARM64 + Linux x86_64 + Windows x86_64</li></ul><p>これらのうちどれを v2.0 に land すべきかの feedback を GitHub Discussions で募集中。</p><h2 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h2><p>v1.35 sub-Issue を review していただいた方、 <code>@kiwa-lab/observability</code> v2.1 pre-release を試していただいた方、 縦深化 pair pattern SSOT を 7-pair grid (3-stage 拡張 2 例) に整理する議論に付き合っていただいた方、 ありがとうございます。 v2.0 へ。</p>',50)])])}const b=a(o,[["render",l]]);export{g as __pageData,b as default};
